 q=copy.deepcopy(qs[1]);q.update(id=f'W09-L42-Q{n:03d}',version=1,status='draft',authorId=AUTHOR,stem=stem,type=typ,difficulty=difficulty,cognitiveSkill='synthesis' if difficulty=='hard' else 'application',subtopic=title,tags=[f'coverage-gap-{n}'],conceptIds=[f'W09-L42-C-gap-{n}'],assumptions=assumptions or [],correctOptionIds=[f'o{key}'],reviewIds=[])
