 b['concepts'].append(dict(id=q['conceptIds'][0],title=title,description=why,slideIds=[],questionIds=[q['id']],status='drafted',topic=q['topic'],subtopic=title,prerequisiteConceptIds=[],examinationAngles=[typ]))
